generated_pydough:
result = organization.WHERE(
    HAS(organization_contact_individual) == 1
).CALCULATE(
    org_name=organization_name,
    contact_count=COUNT(organization_contact_individual)
).TOP_K(1, by=contact_count.DESC()).CALCULATE(
    organization_name=org_name
)

lowest_rated_item = items.WHERE(
    HAS(reviews) == 1
).CALCULATE(
    item_title=title,
    avg_rating=AVG(reviews.rating)
).TOP_K(1, by=avg_rating.ASC()).CALCULATE(
    item_title=item_title
)

school_with_most_players = schools.WHERE(
    HAS(players) == 1
).CALCULATE(
    school_name=school,
    player_count=COUNT(players)
).TOP_K(1, by=player_count.DESC()).CALCULATE(
    denomination=denomination
)

# Find the aircraft that has won the most matches
most_winning_aircraft = Aircraft.WHERE(
    HAS(matches) == 1
).CALCULATE(
    aircraft_name=aircraft,
    wins_count=COUNT(matches)
).TOP_K(1, by=(wins_count.DESC(), aircraft.ASC())).CALCULATE(
    aircraft_name=aircraft_name
)

# Calculate the average claimed amount across all claims and filter
result = insurance_policies.CALCULATE(
    avg_claimed_amount = AVG(claim.amount_claimed)
).claim.WHERE(
    amount_claimed > avg_claimed_amount
).CALCULATE(
    claim_date = date_claim_made,
    settlement_date = date_claim_settled
)

# Find nations that use both English and Dutch
nations_with_english_and_dutch = countries.WHERE(
    HAS(countrylanguages.WHERE(language == "English")) == 1
).WHERE(
    HAS(countrylanguages.WHERE(language == "Dutch")) == 1
)

# Count the number of such nations
result = world_1.CALCULATE(
    count_nations = COUNT(nations_with_english_and_dutch)
)

# Filter gas stations opened after 2000, group by manager, and find the one with most stations
manager_with_most_stations = gas_stations.WHERE(
    open_year > "2000"
).PARTITION(name="managers", by=manager_name).CALCULATE(
    manager_name=manager_name,
    station_count=COUNT(gas_stations)
).TOP_K(1, by=station_count.DESC()).CALCULATE(
    manager_name=manager_name
)

# Find instructors who advise math students, sorted by student's total credits
math_advisors = advisors.WHERE(
    student.dept_name == "Math"
).CALCULATE(
    instructor_name=instructor.name,
    student_credits=student.tot_cred
).ORDER_BY(student_credits.ASC()).CALCULATE(
    instructor_name=instructor_name
)

# Find project details for projects whose research has been published
published_projects = project.WHERE(
    HAS(project_outcome.research_outcome.WHERE(
        CONTAINS(LOWER(outcome_description), "publish")
    )) == 1
).project_outcome.WHERE(
    CONTAINS(LOWER(research_outcome.outcome_description), "publish")
).project.CALCULATE(
    project_details=project_details
)

# Find students who have taken prerequisite courses for "International Finance"
students_with_prereqs = courses.WHERE(
    title == "International Finance"
).prereqs.course.sections.take.student.CALCULATE(
    student_name=name
)

# Find the party that has used services the most and get their email
most_active_party = party.WHERE(
    HAS(party_service) == 1
).CALCULATE(
    party_email=party_email,
    service_count=COUNT(party_service)
).TOP_K(1, by=service_count.DESC()).CALCULATE(
    party_email=party_email
)

# Calculate average weight and filter cars below average, then get their models
cars_below_average_weight = car_1.CALCULATE(
    avg_weight=AVG(cars_datas.weight)
).cars_datas.WHERE(
    weight < avg_weight
).CALCULATE(
    model=car_name.model
)

# Find dorms with TV Lounge but no Study Room
dorms_with_tv_no_study = dorms.WHERE(
    HAS(has_amenities.WHERE(dorm_amenity.amenity_name == "TV Lounge")) == 1
).WHERE(
    HASNOT(has_amenities.WHERE(dorm_amenity.amenity_name == "Study Room")) == 1
).CALCULATE(dorm_name=dorm_name)

# Calculate the average score of all shops at the graph level
below_average_shops = coffee_shop.CALCULATE(
    avg_score=AVG(shops.score)
).shops.WHERE(
    score < avg_score
).CALCULATE(
    shop_id=shop_id,
    address=address
)

# Calculate the average ticket price across all exhibitions and filter exhibitions above average
above_average_exhibitions = theme_gallery.CALCULATE(
    avg_ticket_price=AVG(exhibitions.ticket_price)
).exhibitions.WHERE(
    ticket_price > avg_ticket_price
).CALCULATE(
    artist_name=artist.name,
    theme=theme
)

# Find first names of students who have cat or dog pets
students_with_cats_or_dogs = students.WHERE(
    HAS(has_pets.WHERE(
        (pet.pettype == "cat") | (pet.pettype == "dog")
    )) == 1
).CALCULATE(fname=fname)
